import { useState } from "react";
import { useParams, Link } from "react-router-dom";
import {
  Download,
  Share2,
  RefreshCw,
  ArrowLeft,
  Globe,
  Calendar,
  AlertCircle,
  Zap,
  TrendingUp,
  Copy,
  Check,
  BarChart2,
  Lock,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { ScoreRing } from "@/components/shared/ScoreRing";
import { PillarProgressBar } from "@/components/shared/PillarProgressBar";
import { FindingCard } from "@/components/shared/FindingCard";
import { BrowserFrame } from "@/components/shared/BrowserFrame";
import { PageTransition } from "@/components/shared/PageTransition";
import { SeverityBadge } from "@/components/shared/SeverityBadge";
import {
  getScoreColor,
  getScoreBgLight,
  getScoreLabel,
  getPercentileRank,
  getIndustryBenchmark,
  formatScore,
  getEffortLabel,
  getEffortColor,
  getScoreBgColor,
} from "@/lib/score-utils";
import { CRO_PILLARS } from "@/lib/constants";
import { MOCK_SCANS, MOCK_PILLAR_RESULTS, MOCK_USER } from "@/lib/mock-data";
import { cn } from "@/lib/utils";
import type { Finding, Severity } from "@/types";

// ── Helpers ─────────────────────────────────────────────────────

function formatDateTime(dateStr: string) {
  return new Date(dateStr).toLocaleDateString("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

function deviceLabel(device: string) {
  if (device === "both") return "Desktop & Mobile";
  return device === "desktop" ? "Desktop" : "Mobile";
}

/** Annotation dots positioned over the browser mockup to simulate real audit marks */
const ANNOTATION_DOTS: {
  id: string;
  label: string;
  severity: Severity;
  top: string;
  left: string;
  findingRef: string;
}[] = [
  { id: "a1", label: "CTA below fold", severity: "critical", top: "62%", left: "50%", findingRef: "f_ct01" },
  { id: "a2", label: "Low contrast button", severity: "critical", top: "64%", left: "54%", findingRef: "f_ct02" },
  { id: "a3", label: "No social proof", severity: "critical", top: "18%", left: "75%", findingRef: "f_ts01" },
  { id: "a4", label: "Generic headline", severity: "warning", top: "12%", left: "35%", findingRef: "f_vp01" },
  { id: "a5", label: "Missing trust badges", severity: "critical", top: "85%", left: "48%", findingRef: "f_ts03" },
  { id: "a6", label: "Stock photos", severity: "critical", top: "72%", left: "22%", findingRef: "f_ts02" },
  { id: "a7", label: "Weak subheadline", severity: "warning", top: "20%", left: "38%", findingRef: "f_vp02" },
  { id: "a8", label: "Features compete with hero", severity: "warning", top: "44%", left: "50%", findingRef: "f_vh01" },
];

const severityDotColor: Record<Severity, string> = {
  critical: "bg-red-500 border-red-300 shadow-red-500/40",
  warning: "bg-amber-500 border-amber-300 shadow-amber-500/40",
  info: "bg-blue-500 border-blue-300 shadow-blue-500/40",
  passed: "bg-green-500 border-green-300 shadow-green-500/40",
};

// ── Copy Button ─────────────────────────────────────────────────

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Fallback for older browsers
      const textarea = document.createElement("textarea");
      textarea.value = text;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      document.body.removeChild(textarea);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <button
            onClick={handleCopy}
            className={cn(
              "inline-flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium transition-all",
              copied
                ? "bg-green-50 text-green-600 border border-green-200"
                : "bg-white/80 text-slate-500 border border-slate-200 hover:bg-slate-50 hover:text-slate-700"
            )}
          >
            {copied ? (
              <>
                <Check className="h-3 w-3" />
                Copied
              </>
            ) : (
              <>
                <Copy className="h-3 w-3" />
                Copy
              </>
            )}
          </button>
        </TooltipTrigger>
        <TooltipContent side="top">
          <p>{copied ? "Copied to clipboard!" : "Copy AI suggestion"}</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

// ── Enhanced Finding Wrapper ────────────────────────────────────
// Wraps each FindingCard with effort/impact badges + copy button on AI suggestion

function EnhancedFinding({ finding }: { finding: Finding }) {
  return (
    <div className="relative">
      {/* Effort + Lift badges pinned to the top-right */}
      <div className="absolute -top-2.5 right-4 z-10 flex items-center gap-1.5">
        <span
          className={cn(
            "inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide",
            getEffortColor(finding.effort)
          )}
        >
          <Zap className="h-2.5 w-2.5" />
          {getEffortLabel(finding.effort)}
        </span>
        {finding.estimated_lift && finding.estimated_lift !== "0%" && (
          <span className="inline-flex items-center gap-1 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-violet-600">
            <TrendingUp className="h-2.5 w-2.5" />
            {finding.estimated_lift}
          </span>
        )}
      </div>

      {/* The actual FindingCard */}
      <FindingCard finding={finding} />

      {/* Copy button overlay on AI suggestion (only for non-premium, non-empty suggestions) */}
      {!finding.is_premium && finding.ai_suggestion && (
        <div className="absolute bottom-5 right-5">
          <CopyButton text={finding.ai_suggestion} />
        </div>
      )}
    </div>
  );
}

// ── Stat Card ───────────────────────────────────────────────────

function StatCard({
  label,
  value,
  icon: Icon,
  accent,
  subtitle,
}: {
  label: string;
  value: string | number;
  icon: React.ElementType;
  accent: string;
  subtitle?: string;
}) {
  return (
    <Card className="border-slate-200 shadow-none">
      <CardContent className="flex items-center gap-3.5 p-4">
        <div className={cn("flex h-10 w-10 shrink-0 items-center justify-center rounded-lg", accent)}>
          <Icon className="h-4.5 w-4.5" />
        </div>
        <div className="min-w-0">
          <p className="text-[22px] font-bold leading-tight text-foreground">{value}</p>
          <p className="text-xs text-muted-foreground">{label}</p>
          {subtitle && (
            <p className="mt-0.5 text-[10px] font-medium text-muted-foreground/70">{subtitle}</p>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

// ── Pillar Bar with Benchmark ───────────────────────────────────

function PillarBarWithBenchmark({
  pillar,
  score,
  benchmark,
}: {
  pillar: string;
  score: number;
  benchmark: number;
}) {
  const config = CRO_PILLARS.find((p) => p.key === pillar);
  if (!config) return null;

  const Icon = config.icon;
  const diff = score - benchmark;
  const diffLabel = diff >= 0 ? `+${diff}` : `${diff}`;
  const diffColor = diff >= 0 ? "text-green-600" : "text-red-500";

  return (
    <div className="group">
      <div className="flex items-center gap-3">
        <Icon className="h-4 w-4 shrink-0 text-muted-foreground" />
        <span className="w-36 shrink-0 truncate text-sm text-slate-600">{config.label}</span>
        <div className="relative flex-1">
          {/* Track */}
          <div className="h-2.5 w-full overflow-hidden rounded-full bg-slate-100">
            <div
              className={cn("h-full rounded-full transition-all duration-1000 ease-out", getScoreBgColor(score))}
              style={{ width: `${score}%` }}
            />
          </div>
          {/* Benchmark marker */}
          <TooltipProvider delayDuration={100}>
            <Tooltip>
              <TooltipTrigger asChild>
                <div
                  className="absolute top-1/2 -translate-y-1/2 h-5 w-0.5 bg-slate-800/60 rounded-full"
                  style={{ left: `${benchmark}%` }}
                >
                  <div className="absolute -top-1 left-1/2 -translate-x-1/2 h-1.5 w-1.5 rounded-full bg-slate-700" />
                </div>
              </TooltipTrigger>
              <TooltipContent side="top" className="text-xs">
                <p>Industry avg: {benchmark}/100</p>
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        </div>
        <span className={cn("w-10 text-right text-sm font-semibold", getScoreColor(score))}>
          {formatScore(score)}
        </span>
        <span className={cn("w-12 text-right text-xs font-medium", diffColor)}>
          {diffLabel} avg
        </span>
      </div>
    </div>
  );
}

// ── Main Component ──────────────────────────────────────────────

const AuditReport = () => {
  const { id } = useParams();
  const scan = MOCK_SCANS.find((s) => s.id === id) ?? MOCK_SCANS[0];
  const pillarResults = MOCK_PILLAR_RESULTS.filter((r) => r.scan_id === scan.id);

  // Sort pillars by score ascending (worst first)
  const sortedPillars = [...pillarResults].sort((a, b) => a.score - b.score);

  // Aggregate stats
  const allFindings = pillarResults.flatMap((p) => p.findings);
  const totalFindings = allFindings.length;
  const criticalCount = allFindings.filter((f) => f.severity === "critical").length;
  const quickWinCount = allFindings.filter((f) => f.effort === "quick" && f.severity !== "passed").length;
  const lockedFindings = allFindings.filter((f) => f.is_premium).length;

  // Estimated total lift: parse "X-Y%" patterns and sum the midpoints
  const estimatedTotalLift = allFindings.reduce((sum, f) => {
    const match = f.estimated_lift.match(/(\d+(?:\.\d+)?)-?(\d+(?:\.\d+)?)?%/);
    if (match) {
      const low = parseFloat(match[1]);
      const high = match[2] ? parseFloat(match[2]) : low;
      return sum + (low + high) / 2;
    }
    return sum;
  }, 0);

  // Key issues for overlay and sidebar
  const criticalFindings = allFindings
    .filter((f) => f.severity === "critical" || f.severity === "warning")
    .sort((a, b) => {
      const order: Record<Severity, number> = { critical: 0, warning: 1, info: 2, passed: 3 };
      return order[a.severity] - order[b.severity];
    })
    .slice(0, 5);

  const score = scan.overall_score ?? 0;
  const percentile = getPercentileRank(score);
  const scoreLabel = getScoreLabel(score);

  return (
    <PageTransition>
      <div className="space-y-8">
        {/* ── Breadcrumb ──────────────────────────────────────── */}
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Button variant="ghost" size="sm" asChild className="text-muted-foreground -ml-2 h-auto p-1">
            <Link to="/reports">
              <ArrowLeft className="mr-1 h-3.5 w-3.5" />
              Reports
            </Link>
          </Button>
          <span className="text-slate-300">/</span>
          <span className="truncate text-slate-500">
            {scan.page_title ?? scan.url}
          </span>
        </div>

        {/* ── Report Header ───────────────────────────────────── */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
          <div className="space-y-2">
            <h1 className="text-2xl font-bold text-foreground leading-tight sm:text-[28px]">
              {scan.page_title ?? "Audit Report"}
            </h1>
            <div className="flex items-center gap-2">
              <Globe className="h-3.5 w-3.5 text-muted-foreground" />
              <a
                href={scan.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-sm text-primary hover:underline truncate max-w-md"
              >
                {scan.url}
              </a>
            </div>
            <div className="flex flex-wrap items-center gap-2 text-sm text-muted-foreground">
              <div className="flex items-center gap-1">
                <Calendar className="h-3.5 w-3.5" />
                {scan.completed_at ? formatDateTime(scan.completed_at) : "In progress"}
              </div>
              <Separator orientation="vertical" className="h-3.5" />
              <Badge variant="outline" className="text-xs capitalize">
                {scan.page_type} page
              </Badge>
              <Badge variant="outline" className="text-xs">
                {deviceLabel(scan.device)}
              </Badge>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" className="border-slate-200">
              <Download className="mr-1.5 h-3.5 w-3.5" />
              PDF Report
            </Button>
            <Button variant="outline" size="sm" className="border-slate-200">
              <Share2 className="mr-1.5 h-3.5 w-3.5" />
              Share
            </Button>
            <Button size="sm">
              <RefreshCw className="mr-1.5 h-3.5 w-3.5" />
              Re-scan
            </Button>
          </div>
        </div>

        {/* ── Summary Stats Row ───────────────────────────────── */}
        <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
          <StatCard
            label="Total Findings"
            value={totalFindings}
            icon={BarChart2}
            accent="bg-slate-100 text-slate-600"
            subtitle={`Across ${pillarResults.length} pillars`}
          />
          <StatCard
            label="Critical Issues"
            value={criticalCount}
            icon={AlertCircle}
            accent="bg-red-100 text-red-600"
            subtitle="Fix these first"
          />
          <StatCard
            label="Quick Wins"
            value={quickWinCount}
            icon={Zap}
            accent="bg-green-100 text-green-600"
            subtitle="Low effort, high return"
          />
          <StatCard
            label="Est. Total Lift"
            value={`+${estimatedTotalLift.toFixed(1)}%`}
            icon={TrendingUp}
            accent="bg-violet-100 text-violet-600"
            subtitle="If all recommendations applied"
          />
        </div>

        {/* ── Score Hero ──────────────────────────────────────── */}
        <Card
          className={cn(
            "border-slate-200 shadow-none overflow-hidden",
            getScoreBgLight(score)
          )}
        >
          <CardContent className="p-8">
            <div className="grid grid-cols-1 items-center gap-8 lg:grid-cols-3">
              {/* Giant score ring + percentile */}
              <div className="flex flex-col items-center gap-4 lg:items-center">
                <ScoreRing score={score} size={200} strokeWidth={12} />
                <div className="text-center">
                  <p className="text-sm font-medium text-foreground">
                    Your score of {score} is better than{" "}
                    <span className={cn("font-bold", getScoreColor(score))}>{percentile}%</span>
                    {" "}of landing pages we've analyzed
                  </p>
                  <p className="mt-1 text-xs text-muted-foreground">
                    Rating: <span className="font-semibold">{scoreLabel}</span> — based on {totalFindings} data points across 7 CRO pillars
                  </p>
                </div>
              </div>

              {/* Pillar scores with benchmarks */}
              <div className="space-y-3.5 lg:col-span-2">
                <div className="mb-4 flex items-center justify-between">
                  <h3 className="text-sm font-semibold uppercase tracking-wider text-muted-foreground">
                    CRO Pillar Scores
                  </h3>
                  <div className="flex items-center gap-1.5 text-[10px] text-muted-foreground">
                    <div className="h-3 w-0.5 rounded-full bg-slate-800/60" />
                    <span>Industry benchmark</span>
                  </div>
                </div>
                {sortedPillars.map((result) => (
                  <PillarBarWithBenchmark
                    key={result.pillar}
                    pillar={result.pillar}
                    score={result.score}
                    benchmark={result.benchmark}
                  />
                ))}
                {/* Fallback bars for pillars without results */}
                {CRO_PILLARS.filter(
                  (p) => !pillarResults.some((r) => r.pillar === p.key)
                ).map((pillar) => (
                  <PillarBarWithBenchmark
                    key={pillar.key}
                    pillar={pillar.key}
                    score={0}
                    benchmark={getIndustryBenchmark(pillar.key)}
                  />
                ))}
              </div>
            </div>
          </CardContent>
        </Card>

        {/* ── Annotated Mockup + Key Issues Sidebar ───────────── */}
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-5">
          {/* Annotated Browser Mockup */}
          <div className="lg:col-span-3">
            <BrowserFrame url={scan.url}>
              <div className="relative h-[420px] overflow-hidden bg-gradient-to-br from-slate-50 via-white to-slate-50">
                {/* Simulated page structure */}
                <div className="absolute inset-0 p-4">
                  {/* Nav bar skeleton */}
                  <div className="flex items-center justify-between px-3 py-2">
                    <div className="h-5 w-24 rounded bg-slate-200/80" />
                    <div className="flex gap-3">
                      <div className="h-3 w-12 rounded bg-slate-200/60" />
                      <div className="h-3 w-12 rounded bg-slate-200/60" />
                      <div className="h-3 w-12 rounded bg-slate-200/60" />
                      <div className="h-6 w-16 rounded-md bg-slate-200/80" />
                    </div>
                  </div>

                  {/* Hero section skeleton */}
                  <div className="mt-8 flex flex-col items-center px-6 text-center">
                    <div className="h-6 w-72 rounded bg-slate-200/80 mb-3" />
                    <div className="h-4 w-56 rounded bg-slate-200/50 mb-2" />
                    <div className="h-4 w-48 rounded bg-slate-200/40 mb-6" />
                    {/* Wireframe CTA area */}
                    <div className="h-3 w-36 rounded bg-slate-200/30" />
                  </div>

                  {/* Features grid skeleton */}
                  <div className="mt-10 grid grid-cols-3 gap-4 px-6">
                    {[1, 2, 3].map((i) => (
                      <div key={i} className="rounded-lg border border-slate-200/50 bg-white/60 p-3">
                        <div className="mx-auto mb-2 h-6 w-6 rounded bg-slate-200/60" />
                        <div className="mx-auto h-3 w-16 rounded bg-slate-200/50 mb-1.5" />
                        <div className="mx-auto h-2 w-20 rounded bg-slate-200/30" />
                      </div>
                    ))}
                  </div>

                  {/* Below-fold section skeleton */}
                  <div className="mt-8 px-6">
                    <div className="mx-auto h-4 w-40 rounded bg-slate-200/60 mb-4" />
                    <div className="grid grid-cols-2 gap-3">
                      <div className="rounded-lg border border-slate-200/40 bg-white/40 p-4">
                        <div className="h-3 w-full rounded bg-slate-200/30 mb-2" />
                        <div className="h-3 w-3/4 rounded bg-slate-200/20" />
                      </div>
                      <div className="rounded-lg border border-slate-200/40 bg-white/40 p-4">
                        <div className="h-3 w-full rounded bg-slate-200/30 mb-2" />
                        <div className="h-3 w-2/3 rounded bg-slate-200/20" />
                      </div>
                    </div>
                  </div>

                  {/* CTA area at bottom */}
                  <div className="mt-6 flex justify-center">
                    <div className="h-8 w-32 rounded-lg bg-blue-200/40 border border-blue-300/30" />
                  </div>
                </div>

                {/* Annotation dots */}
                {ANNOTATION_DOTS.map((dot) => (
                  <TooltipProvider key={dot.id} delayDuration={0}>
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <button
                          className={cn(
                            "absolute z-20 flex h-5 w-5 items-center justify-center rounded-full border-2 text-[9px] font-bold text-white shadow-lg animate-pulse cursor-pointer",
                            severityDotColor[dot.severity]
                          )}
                          style={{ top: dot.top, left: dot.left, transform: "translate(-50%, -50%)" }}
                        >
                          {dot.severity === "critical" ? "!" : "i"}
                        </button>
                      </TooltipTrigger>
                      <TooltipContent side="top" className="max-w-xs">
                        <div className="flex items-center gap-2">
                          <SeverityBadge severity={dot.severity} />
                          <span className="text-xs font-medium">{dot.label}</span>
                        </div>
                      </TooltipContent>
                    </Tooltip>
                  </TooltipProvider>
                ))}

                {/* Overlay gradient at bottom to suggest more content */}
                <div className="absolute bottom-0 left-0 right-0 h-16 bg-gradient-to-t from-white to-transparent" />
              </div>
            </BrowserFrame>
            <p className="mt-2 text-center text-[11px] text-muted-foreground">
              Hover over annotations to see issues found at each page section
            </p>
          </div>

          {/* Key Issues Sidebar */}
          <Card className="border-slate-200 shadow-none lg:col-span-2">
            <CardHeader className="pb-3">
              <CardTitle className="flex items-center justify-between">
                <div className="flex items-center gap-2 text-base font-semibold">
                  <AlertCircle className="h-4 w-4 text-red-500" />
                  Top Issues
                </div>
                <Badge variant="outline" className="text-[10px] font-medium">
                  {criticalCount} critical
                </Badge>
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-2.5">
              {criticalFindings.map((finding, idx) => (
                <div
                  key={finding.id}
                  className="flex items-start gap-3 rounded-lg border border-slate-100 p-3 transition-colors hover:bg-slate-50"
                >
                  <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-slate-100 text-[10px] font-bold text-slate-500">
                    {idx + 1}
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <SeverityBadge severity={finding.severity} />
                      <span
                        className={cn(
                          "inline-flex items-center gap-0.5 rounded-full border px-1.5 py-0 text-[9px] font-semibold uppercase",
                          getEffortColor(finding.effort)
                        )}
                      >
                        <Zap className="h-2 w-2" />
                        {getEffortLabel(finding.effort)}
                      </span>
                    </div>
                    <p className="text-sm text-slate-700 leading-snug">{finding.title}</p>
                    {finding.estimated_lift && finding.estimated_lift !== "0%" && (
                      <p className="mt-1 text-[11px] text-violet-600 font-medium">
                        Est. lift: {finding.estimated_lift}
                      </p>
                    )}
                  </div>
                </div>
              ))}

              {lockedFindings > 0 && (
                <>
                  <Separator className="my-2" />
                  <div className="flex items-center gap-2 rounded-lg bg-amber-50 border border-amber-200/60 p-3">
                    <Lock className="h-3.5 w-3.5 text-amber-600" />
                    <p className="text-xs text-amber-700">
                      <span className="font-semibold">{lockedFindings} more findings</span> available on Pro
                    </p>
                  </div>
                </>
              )}
            </CardContent>
          </Card>
        </div>

        {/* ── Detailed Findings (Tabbed) ──────────────────────── */}
        <Card className="border-slate-200 shadow-none">
          <CardHeader>
            <CardTitle className="text-base font-semibold">Detailed Findings</CardTitle>
            <p className="text-sm text-muted-foreground">
              Every finding includes the current issue, a specific recommendation, and an AI-generated suggestion you can copy and implement.
            </p>
          </CardHeader>
          <CardContent>
            <Tabs defaultValue={sortedPillars[0]?.pillar ?? "value_proposition"}>
              <TabsList className="mb-6 flex w-full flex-wrap gap-1 bg-transparent h-auto p-0">
                {CRO_PILLARS.map((pillar) => {
                  const result = pillarResults.find((r) => r.pillar === pillar.key);
                  const findingCount = result?.findings.length ?? 0;
                  const critCount = result?.findings.filter((f) => f.severity === "critical").length ?? 0;

                  return (
                    <TabsTrigger
                      key={pillar.key}
                      value={pillar.key}
                      className="rounded-lg border border-transparent px-3 py-2 text-sm data-[state=active]:border-primary/20 data-[state=active]:bg-primary/5 data-[state=active]:text-primary"
                    >
                      {pillar.label}
                      {findingCount > 0 && (
                        <span className={cn(
                          "ml-1.5 rounded-full px-1.5 py-0.5 text-xs",
                          critCount > 0
                            ? "bg-red-100 text-red-700"
                            : "bg-slate-100 text-slate-600"
                        )}>
                          {findingCount}
                        </span>
                      )}
                    </TabsTrigger>
                  );
                })}
              </TabsList>

              {CRO_PILLARS.map((pillar) => {
                const result = pillarResults.find((r) => r.pillar === pillar.key);
                const benchmark = result?.benchmark ?? getIndustryBenchmark(pillar.key);

                return (
                  <TabsContent key={pillar.key} value={pillar.key}>
                    {result && result.findings.length > 0 ? (
                      <div className="space-y-5">
                        {/* Pillar score summary with benchmark */}
                        <div className="flex items-center gap-4 rounded-xl bg-slate-50 p-5">
                          <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-white border border-slate-200">
                            <pillar.icon className="h-5 w-5 text-slate-600" />
                          </div>
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-semibold text-foreground">{pillar.label}</p>
                            <p className="text-xs text-muted-foreground">{pillar.description}</p>
                          </div>
                          <div className="text-right">
                            <span className={cn("text-2xl font-bold", getScoreColor(result.score))}>
                              {result.score}
                            </span>
                            <span className="text-sm text-muted-foreground">/100</span>
                            <div className="mt-0.5 text-[11px] text-muted-foreground">
                              Industry avg:{" "}
                              <span className="font-semibold">{benchmark}</span>
                              {result.score >= benchmark ? (
                                <span className="ml-1 text-green-600">
                                  (+{result.score - benchmark})
                                </span>
                              ) : (
                                <span className="ml-1 text-red-500">
                                  ({result.score - benchmark})
                                </span>
                              )}
                            </div>
                          </div>
                        </div>

                        {/* Findings */}
                        {result.findings.map((finding) => (
                          <EnhancedFinding key={finding.id} finding={finding} />
                        ))}
                      </div>
                    ) : (
                      <div className="py-12 text-center text-sm text-muted-foreground">
                        No findings for this pillar yet.
                      </div>
                    )}
                  </TabsContent>
                );
              })}
            </Tabs>
          </CardContent>
        </Card>

        {/* ── Bottom Upgrade CTA ──────────────────────────────── */}
        {lockedFindings > 0 && (
          <Card className="relative overflow-hidden border-primary/20 shadow-none">
            {/* Gradient background */}
            <div className="absolute inset-0 bg-gradient-to-br from-primary/5 via-violet-50 to-primary/10" />
            <CardContent className="relative flex flex-col items-center p-10 text-center">
              <div className="mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-primary/10">
                <Lock className="h-6 w-6 text-primary" />
              </div>
              <h3 className="text-xl font-bold text-foreground sm:text-2xl">
                {lockedFindings} findings are locked on this report
              </h3>
              <p className="mt-3 max-w-lg text-sm text-muted-foreground leading-relaxed">
                You're seeing {totalFindings - lockedFindings} of {totalFindings} total findings.
                The locked findings include{" "}
                <span className="font-medium text-foreground">AI-rewritten copy alternatives</span>,{" "}
                <span className="font-medium text-foreground">specific code fixes</span>, and{" "}
                <span className="font-medium text-foreground">design recommendations</span> that
                could drive an additional estimated{" "}
                <span className="font-semibold text-primary">
                  {(estimatedTotalLift * 0.4).toFixed(1)}% conversion lift
                </span>.
              </p>
              <div className="mt-2 flex items-center gap-4 text-xs text-muted-foreground">
                <span className="flex items-center gap-1">
                  <Check className="h-3 w-3 text-green-500" />
                  All findings unlocked
                </span>
                <span className="flex items-center gap-1">
                  <Check className="h-3 w-3 text-green-500" />
                  AI copy rewrites
                </span>
                <span className="flex items-center gap-1">
                  <Check className="h-3 w-3 text-green-500" />
                  PDF export
                </span>
                <span className="flex items-center gap-1">
                  <Check className="h-3 w-3 text-green-500" />
                  Score monitoring
                </span>
              </div>
              <Button asChild size="lg" className="mt-6 rounded-xl px-10 font-semibold text-base">
                <Link to="/pricing">
                  Unlock Full Report — $49/month
                </Link>
              </Button>
              <p className="mt-3 text-xs text-muted-foreground">
                14-day free trial. Cancel anytime.
                {MOCK_USER.scan_limit - MOCK_USER.scans_used > 0 && (
                  <span>
                    {" "}Or continue with {MOCK_USER.scan_limit - MOCK_USER.scans_used} free scan{MOCK_USER.scan_limit - MOCK_USER.scans_used !== 1 ? "s" : ""} remaining.
                  </span>
                )}
              </p>
            </CardContent>
          </Card>
        )}
      </div>
    </PageTransition>
  );
};

export default AuditReport;
